import sys, json
sys.path.insert(0,'/app')
from binkeep.context import Context
from binkeep.bins import normalize
ctx=Context('data','x')
for packs in (True, False):
    st={}
    def setq(sku,b,q):
        st.setdefault(sku,{})
        if q: st[sku][b]=q
        else: st[sku].pop(b,None)
    bad=0
    for e in ctx.entries:
        op=e['op']
        if e.get('v')==2:
            for x in e['effects']:
                if st.get(e['sku'],{}).get(x['bin'],0)!=x['before']: bad+=1
                setq(e['sku'],x['bin'],x['after'])
        else:
            s=e['sku']; g=lambda b: st.get(s,{}).get(b,0)
            if op=='receive':
                q=e['qty']*(ctx.items[s].pack_size if packs and e.get('uom')=='pk' else 1)
                b=normalize(e['bin']); setq(s,b,g(b)+q)
            elif op=='issue':
                for b,q in e['picks']: b=normalize(b); setq(s,b,g(b)-q)
            elif op=='move':
                a,b=normalize(e['from']),normalize(e['to']); setq(s,a,g(a)-e['qty']); setq(s,b,g(b)+e['qty'])
            elif op in('count','fix'):
                setq(s,normalize(e['bin']),e['qty'])
    cur={k:v for k,v in ctx.store._stock.items() if v}
    st={k:v for k,v in st.items() if v}
    print(packs, bad, st==cur, any(q<0 for v in st.values() for q in v.values()))
EOF
